import javax.swing.*;import java.awt.*;import java.awt.event.*;
public class ConverterLambda extends JFrame {private final JTextField amount=new JTextField(10);private final JComboBox<String> target=new JComboBox<>(new String[]{"USD","EUR"});private final JLabel result=new JLabel(" ");private static double rate(String c){return c.equals("USD")?.012:.011;}public ConverterLambda(){super("Currency Converter");setLayout(new FlowLayout());JButton b=new JButton("Convert");add(new JLabel("INR"));add(amount);add(target);add(b);add(result);ActionListener convert=e->convert();b.addActionListener(convert);amount.addActionListener(convert);addWindowListener(new WindowAdapter(){public void windowClosing(WindowEvent e){dispose();}});pack();setLocationRelativeTo(null);}private void convert(){try{double v=Double.parseDouble(amount.getText().trim());if(!Double.isFinite(v)||v<0)throw new NumberFormatException();result.setText(String.format("%.2f %s",v*rate((String)target.getSelectedItem()),target.getSelectedItem()));JOptionPane.showMessageDialog(this,result.getText(),"Conversion result",JOptionPane.INFORMATION_MESSAGE);}catch(NumberFormatException ex){result.setText("Invalid amount");JOptionPane.showMessageDialog(this,"Invalid amount","Input error",JOptionPane.ERROR_MESSAGE);}}public static void main(String[]x){SwingUtilities.invokeLater(()->new ConverterLambda().setVisible(true));}}
